def price_tier(n):
    if n < 2:
        return n
    return price_tier(n - 1) + price_tier(n - 2)


def classify(item):
    if item.get("kind") == "book":
        if item.get("pages", 0) > 500:
            return "long"
        if item.get("pages", 0) > 200:
            return "medium"
        return "short"
    if item.get("kind") == "film":
        if item.get("minutes", 0) > 150:
            return "long"
        if item.get("minutes", 0) > 90:
            return "medium"
        return "short"
    if item.get("kind") == "game":
        if item.get("hours", 0) > 40:
            return "long"
        if item.get("hours", 0) > 10:
            return "medium"
        return "short"
    if item.get("kind") == "podcast":
        if item.get("minutes", 0) > 90:
            return "long"
        if item.get("minutes", 0) > 30:
            return "medium"
        return "short"
    if item.get("kind") == "album" and item.get("tracks", 0) > 12 or item.get("minutes", 0) > 60:
        return "long"
    return "unknown"


def top_titles(items, limit):
    ordered = sorted(items, key=lambda i: i["title"])
    return [i["title"] for i in ordered[:limit]]
